    (N'TKT-00042689', CAST(N'2026-09-17T11:41:06.317' AS [datetime]), N'003', N'AAVILA', N'017', N'103', N'307', N'Al momento de ingresar al sistema remoto, luego comercial, la computadora inicio la apertura de varias paginas de la misma a la vez, imposibilitando el poder cerrar todo el sistema , luego de ello, se cerro y en la pagina principal inicio nuevamente pero a querer abrirse el sistema remoto, y no permitia realizar ningun cierre u otra funcion ', N'AT', N'SCHIRA', N'001', N'241', N'017', CAST(N'2026-09-17T15:14:38.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'AAVILA', N'SCHIRA', CAST(N'2026-09-18T10:55:32.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 241, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'INCIDENCIA EN SISTEMA REMOTO', NULL, N'se atendio lo reportado.', NULL),
