    (N'TKT-00042690', CAST(N'2026-09-17T13:13:42.290' AS [datetime]), N'002', N'SSALDAÑA', N'046', N'116', N'371', N'Buenas tardes.' + NCHAR(13) + N'' + NCHAR(10) + N'' + NCHAR(13) + N'' + NCHAR(10) + N'Por favor tu apoyo con respecto a este link:' + NCHAR(13) + N'' + NCHAR(10) + N'http://190.116.22.130:2384/MonitoreoInventario/visorreporte311.aspx' + NCHAR(13) + N'' + NCHAR(10) + N'por medio de link se genera un reporte para poder tener el control de las guías generadas, pero hay casos que no aparecen algunos registros como del almacen de COMPOSTURA, o tambien los registros de CURTIEMBRE BUENAVENTURA (su transacción es DEVOLUCIÓN O/C)' + NCHAR(13) + N'' + NCHAR(10) + N'' + NCHAR(13) + N'' + NCHAR(10) + N'De tener alguna duda de lo antes mencionado me comentas.', N'PE', NULL, N'001', NULL, NULL, NULL, NULL, NULL, N'N', N'SSALDAÑA', N'SSALDAÑA', CAST(N'2026-09-17T13:13:42.290' AS [datetime]), NULL, NULL, NULL, 1, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'REPORTE DE GUIAS', NULL, NULL, NULL),
