    (N'TKT-00042688', CAST(N'2026-09-17T10:17:07.327' AS [datetime]), N'003', N'LFARFAN', N'017', N'111', N'339', N'NO RESPONDE EL PROGRAMA  Y NINGUANA  DE SUS HERRAMIENTAS', N'AS', N'MDELACRUZ', N'001', N'244', NULL, CAST(N'2026-09-17T10:43:33.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'LFARFAN', N'ROBREGON', CAST(N'2026-09-17T10:43:33.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 244, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'FALLA EN EL PROGRAMA OFFICE', NULL, NULL, NULL),
    (N'TKT-00042684', CAST(N'2026-09-17T09:18:14.753' AS [datetime]), N'002', N'MMOSTACERO', N'013', N'123', N'417', N'Al realizar la carga de las guías en el sistema de distribución y generar la Guía de Transportistas (GT), el sistema debería generar una GT por cada cliente y dirección de entrega.' + NCHAR(13) + N'' + NCHAR(10) + N'Sin embargo, en esta ocasión se generó una sola GT agrupando a varios clientes, lo cual no corresponde al proceso establecido.' + NCHAR(13) + N'' + NCHAR(10) + N'Por favor, revisar la configuración o lógica de generación de las GT y realizar la corrección correspondiente, a fin de que se genere una GT independiente por cliente y dirección.' + NCHAR(13) + N'' + NCHAR(10) + N'' + NCHAR(13) + N'' + NCHAR(10) + N'GT VJ01-00010635', N'PE', NULL, N'001', NULL, NULL, NULL, NULL, NULL, N'N', N'MMOSTACERO', N'MMOSTACERO', CAST(N'2026-09-17T09:18:14.753' AS [datetime]), NULL, NULL, NULL, 1, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'ERROR EN EMISION DE GUIAS D ETRANSPORTISTA', NULL, NULL, NULL),
    (N'TKT-00042658', CAST(N'2026-09-15T16:05:51.997' AS [datetime]), N'002', N'GNIETO', N'026', N'136', N'501', N'Buenas tardes, por favor su apoyo generando un nuevo usuario en Facele para el supervisor Hugo Ortiz Calle, del área de Prefinito, a fin de que pueda gestionar la emisión de las guías de remisión correspondientes.' + NCHAR(10) + N'' + NCHAR(10) + N'', N'AT', N'JSILVA', N'003', N'252', N'026', CAST(N'2026-09-17T08:40:26.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'GNIETO', N'JSILVA', CAST(N'2026-09-17T08:53:02.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 252, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'CREACION DE NUEVO USUARIO SUPERVISOR DE PREFINITO', NULL, N'Se le brindó el acceso al link de guias al usuario solicitado', NULL),
    (N'TKT-00042675', CAST(N'2026-09-16T12:35:55.990' AS [datetime]), N'002', N'ERIVEROS', N'013', N'118', N'381', N'Buenas tardes' + NCHAR(10) + N'estimados' + NCHAR(10) + N'' + NCHAR(10) + N'Se  quiere ingresar al  BI Rotación de mercadería de  de JLd pero el sistema no lo permite, su apoyo ', N'AT', N'JSILVA', N'001', N'244', N'013', CAST(N'2026-09-17T08:44:32.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'ERIVEROS', N'JSILVA', CAST(N'2026-09-17T08:46:36.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 244, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'ACCESO AL BI ROTACION DE MERCADERIA', NULL, N'Se hizo cambio de ruta para que pueda abrir correctamente el archivo', NULL),
    (N'TKT-00042674', CAST(N'2026-09-16T12:34:49.557' AS [datetime]), N'002', N'FSINCHI', N'013', N'115', N'362', N'Buenas tarde;' + NCHAR(10) + N'Su apoyo con el RQ 172535 es del almacén de PTA-1 no me permite confirmar por el tema del comprometido', N'AT', N'JSILVA', N'001', N'236', N'013', CAST(N'2026-09-16T14:38:47.000' AS [datetime]), N'JSILVA', NULL, N'N', N'FSINCHI', N'JSILVA', CAST(N'2026-09-17T08:45:54.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'COMPROMETIDO', NULL, N'Se hicieron cambios por BD añadiendo comprometidos al Item faltante', NULL),
    (N'TKT-00042682', CAST(N'2026-09-16T18:39:25.657' AS [datetime]), N'002', N'AAVILA', N'017', N'120', N'393', N'Buenas tardes estimados ' + NCHAR(10) + N'Por favor su apoyo con la modificación de los precios del sistema RMS ya que no arroja el mismo precio que jala en el P.O.S ', N'AT', N'ROBREGON', N'001', N'237', N'017', CAST(N'2026-09-17T08:40:36.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'AAVILA', N'ROBREGON', CAST(N'2026-09-17T08:43:21.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 237, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'ERROR EN LOS PRECIOS', NULL, N'Se le informa al usuario que el primer filtro acerca de los precios en el POS y RMS se debe proceder con su supervisora para que se revise la derivación con las coordinadoras de marca (usuarios que cargan los precios). Ya nos comunicamos con una de las supervisoras para que lo revise y ya debería de estar corregido. Validar.', NULL),
    (N'TKT-00042681', CAST(N'2026-09-16T18:15:18.627' AS [datetime]), N'002', N'SCAVERO', N'056', N'114', N'353', N'Favor su apoyo,' + NCHAR(10) + N'' + NCHAR(10) + N'estos son caso ya atendidos, pero desde el mes pasado se viene reportando que se generan varios pedidos de un mismo dscto, generando asi varios PDF' + NCHAR(10) + N'' + NCHAR(10) + N'favor pronta solucion ', N'AS', N'HCRISPIN', N'001', N'252', NULL, CAST(N'2026-09-17T08:36:51.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'SCAVERO', N'ROBREGON', CAST(N'2026-09-17T08:36:51.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 252, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'PEDIDO CON MISMO DSCTO SE GENERAN VARIOS N° DE PEDIDO', NULL, NULL, NULL),
    (N'TKT-00042680', CAST(N'2026-09-16T18:08:16.610' AS [datetime]), N'002', N'ICONDORI', N'056', N'114', N'352', N'Solicito que se evalué y corrija el siguiente inconveniente que se presenta en el catalogo web .' + NCHAR(10) + N'Al momento de cargar un pedido se desglosa en varios pedidos , y al momento de transferir y facturar genera mas facturas e guías y genera molestias en los clientes entregarles tantas facturas e guías .Ellos sugieran que sea en un solo PDF como siempre se ha trabajado .ADJUNTO FOTOS .', N'AS', N'HCRISPIN', N'003', N'234', NULL, CAST(N'2026-09-17T08:36:44.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'ICONDORI', N'ROBREGON', CAST(N'2026-09-17T08:36:44.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 234, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'DESGLOSE INNECESARIO DE PEDIDOS EN CATALOGO WEB ', NULL, NULL, NULL),
    (N'TKT-00042679', CAST(N'2026-09-16T17:53:18.633' AS [datetime]), N'002', N'MGTAPIA', N'056', N'114', N'352', N'Por medio del presente ,solicito se evalué y corrija el siguiente inconveniente que se presenta en el catalogo web.' + NCHAR(10) + N'Al momento de cargar un pedido -por ejemplo de 7 cajas , el sistema automáticamente lo desglosa en 7 pedidos distintos ,cuando debería mantenerse como un único pedido con la cantidad total .Adjunto fotos del ejemplo.', N'AS', N'HCRISPIN', N'003', N'234', NULL, CAST(N'2026-09-17T08:36:35.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'MGTAPIA', N'ROBREGON', CAST(N'2026-09-17T08:36:35.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 234, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'DESGLOSE INNECESARIO DE PEDIDOS EN CATALOGO WEB ', NULL, NULL, NULL),
    (N'TKT-00042673', CAST(N'2026-09-16T11:41:11.167' AS [datetime]), N'002', N'ATOCRE', N'057', N'122', N'409', N'Por favor revisar el detalle de Generador de consultas, ya que no me permite buscar reportes de determinados clientes ( filtro por clientenúmero)', N'AT', N'ROBREGON', N'001', N'236', N'057', CAST(N'2026-09-16T13:40:13.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'ATOCRE', N'ROBREGON', CAST(N'2026-09-16T15:47:13.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'NO ME DEJA REALIZAR BUSQUEDA FILTRADA POR NRO DE CLIENTE', NULL, N'Se revisó el caso y se procedió a actualizar la lógica del consultor para que permite buscar multiples clientes por su codigo. Validar y dar la conformidad.', NULL),
    (N'TKT-00042677', CAST(N'2026-09-16T15:17:29.993' AS [datetime]), N'003', N'NIPEREZ', N'049', N'111', N'339', N'No responde el sistema office, no se puede enviar correos ni utilizar ninguna herramienta del office.', N'AS', N'MDELACRUZ', N'001', N'244', NULL, CAST(N'2026-09-16T15:22:15.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'NIPEREZ', N'ROBREGON', CAST(N'2026-09-16T15:22:15.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 244, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N' Falla en programa de office', NULL, NULL, NULL),
    (N'TKT-00042665', CAST(N'2026-09-15T23:58:04.890' AS [datetime]), N'002', N'GFARRO', N'046', N'122', N'409', N'Estimados se quiere despachar un pedido de produccion de accesorios, sin embargo al generar el pedido parcial en el spring comercial solo muestra 5 de las 8 unidades que tenemos en stock de lote 6001045375.' + NCHAR(10) + N'Urgente su apoyo en revisar, se envia correo al respecto', N'AT', N'PACRUZ', N'001', N'236', N'046', CAST(N'2026-09-16T08:22:36.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'GFARRO', N'PACRUZ', CAST(N'2026-09-16T15:09:29.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'STOCK NO SE VISUALIZA EN SPRING', NULL, N'Se hizo el update de la suma de stock en el spring', NULL),
    (N'TKT-00042669', CAST(N'2026-09-16T10:30:19.807' AS [datetime]), N'002', N'SSALDAÑA', N'046', N'116', N'371', N'Buenos días.' + NCHAR(10) + N'por favor su apoyo con los siguientes documentos de la compañia Industrias Windsor' + NCHAR(10) + N'TI01-00049076' + NCHAR(10) + N'TI01-00049081' + NCHAR(10) + N'aún no aparece en la plataforma de FACELE, ya ha pasado una hora desde su emision.' + NCHAR(10) + N'', N'AT', N'PACRUZ', N'001', N'252', N'046', CAST(N'2026-09-16T14:48:40.000' AS [datetime]), N'PACRUZ', NULL, N'N', N'SSALDAÑA', N'PACRUZ', CAST(N'2026-09-16T15:08:58.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 252, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'DEMORA EN DOCUMENTOS', NULL, N'Los documentos no cuentan con secuencia de direcciones', NULL),
    (N'TKT-00042676', CAST(N'2026-09-16T14:48:00.550' AS [datetime]), N'002', N'SSALDAÑA', N'046', N'116', N'371', N'buenas tardes.' + NCHAR(10) + N'' + NCHAR(10) + N'se ha generado la guia: TJ01-00034031 de la compañia JLD pero hasta el momento no aparece, por favor su apoyo Urgente.', N'AT', N'PACRUZ', N'001', N'252', N'046', CAST(N'2026-09-16T14:48:24.000' AS [datetime]), N'PACRUZ', NULL, N'N', N'SSALDAÑA', N'PACRUZ', CAST(N'2026-09-16T15:08:36.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 252, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'DEMORA EN DOCUMENTOS', NULL, N'Se procedió con la subida de los documentos a facele', NULL),
    (N'TKT-00042618', CAST(N'2026-09-10T18:23:59.727' AS [datetime]), N'002', N'FSINCHI', N'013', N'115', N'361', N'Buenas tardes :' + NCHAR(10) + N'Actualmente, las cantidades se encuentran agrupadas únicamente por Ítem; sin embargo, se solicitó que dicha agrupación también considere el Lote, de manera que las cantidades puedan visualizarse correctamente diferenciadas por Ítem y Lote', N'CF', N'JSILVA', N'001', N'252', N'013', CAST(N'2026-09-11T08:01:05.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'FSINCHI', N'JSILVA', CAST(N'2026-09-16T14:49:16.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 252, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'diferenciadas por Ítem y Lote', NULL, N'Se hicieron compromisos por BD para que el usuario pueda confirmar el RQ', NULL),
    (N'TKT-00042671', CAST(N'2026-09-16T10:58:56.627' AS [datetime]), N'002', N'RSHIMABUKURO', N'030', N'115', N'357', N'Buenos dias ' + NCHAR(10) + N'' + NCHAR(10) + N'Su apoyo para la creacion de credenciales y accesos a los sistemas para la Planner Comercial Alexandra Prieto que se incorpora el dia Lunes 21' + NCHAR(10) + N'' + NCHAR(10) + N'Alexandra Prieto Soto' + NCHAR(10) + N'DNI: 74644324', N'AS', N'JSILVA', N'003', N'244', NULL, CAST(N'2026-09-16T11:20:52.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'RSHIMABUKURO', N'ROBREGON', CAST(N'2026-09-16T11:20:52.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 244, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Accesos y Credenciales Planner Comercial', NULL, NULL, NULL),
    (N'TKT-00042668', CAST(N'2026-09-16T10:25:40.330' AS [datetime]), N'002', N'ABMINAYA', N'049', N'136', N'500', N'NO ME PERMITE EMITIR NI SUBIR NIGUNA GUIA , ME SALE "NO TIENES ACSESO A NINGUNA COMPAÑIA"' + NCHAR(10) + N'ADJUNTO IMAGEN :', N'AT', N'ROBREGON', N'001', N'236', N'017', CAST(N'2026-09-16T10:33:51.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'ABMINAYA', N'ROBREGON', CAST(N'2026-09-16T10:34:15.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'NO ME PERMITE SUBIR NI EMITIR NINGUNA GUIA ', NULL, N'Se le refrescó el acceso. Validar y dar la conformidad.', NULL),
    (N'TKT-00042667', CAST(N'2026-09-16T10:23:35.713' AS [datetime]), N'002', N'ABMINAYA', N'049', N'136', N'500', N'EN EL SISTEMA DE GUIAS DE REMISION NO ME PERMITE SUBIR NI EMITIR NINGUNA GUIA, ME SALE "NO TIENES ' + NCHAR(10) + N'ACSESO A NINGUNA COMPAÑIA" ' + NCHAR(10) + N'ADJUNTO IMAGEN:', N'NP', N'ROBREGON', N'001', N'236', NULL, CAST(N'2026-09-16T10:31:20.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'ABMINAYA', N'ROBREGON', CAST(N'2026-09-16T10:31:20.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'NO ME PERMITE SUBIR NI EMITIR NINGUNA GUIA ', NULL, NULL, NULL),
    (N'TKT-00042605', CAST(N'2026-09-09T15:54:57.613' AS [datetime]), N'002', N'GRAMOS', N'004', N'115', N'362', N'Buenas tardes;' + NCHAR(10) + N'En el reporte de rentabilidad de la tienda chimbote el precio unitario venta y total venta de algunas transacciones están con cero, revisar.', N'CF', N'ROBREGON', N'001', N'237', N'004', CAST(N'2026-09-11T16:06:38.000' AS [datetime]), N'ROBREGON', NULL, N'N', N'GRAMOS', N'ROBREGON', CAST(N'2026-09-16T10:04:48.000' AS [datetime]), NULL, NULL, NULL, 3, 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'ERROR REPORTE DE RENTABILIDAD CHIMBOTE', NULL, N'Se revisó el caso y se observó que el reporte no ubicaba la información de 3 ND que se realizaron de manera extraordinaria. Se procedió a agregar estos documentos para que al reprocesar pueda sacar su precio unitario venta y total. Adicionalmente se ha encontrado una NC B118-0048364 que a nivel de documento se encuentra anulado pero a nivel de transacción no y por ende no muestra esa información.', NULL),
